// Assuming lfs_gstate_t contains at least these fields for wear leveling:
// - block_wear: array of wear counters for each block
// - block_used: array of flags indicating if blocks are used
// - block_age: array of timestamps for block usage
// - crc: checksum for the global state

// Size of the global state structure (assuming 256 blocks as common in LittleFS)
constexpr std::size_t LFS_GSTATE_SIZE = 256;

// Perform XOR operation on all fields of the global state
for (std::size_t i = 0; i < LFS_GSTATE_SIZE; ++i) {
    // XOR block wear counters
    a->block_wear[i] ^= b->block_wear[i];

    // XOR block used flags
    a->block_used[i] ^= b->block_used[i];

    // XOR block age timestamps
    a->block_age[i] ^= b->block_age[i];
}

// XOR the CRC checksum
a->crc ^= b->crc;

